<?php
// ============================================================
// Station-Dependent Module Configuration API
// backend/api/station_module_api.php
// Handles all module configuration per station
// ============================================================  if (session_status() === PHP_SESSION_NONE) session_start();
require_once __DIR__ . '/../lib.php';
require_once __DIR__ . '/../../public/db_connect.php';
require_login();  header('Content-Type: application/json');  $me = current_user();
$role = role_key($me['role'] ?? '');  // Only SuperAdmin/Developer access
if ($role !== 'superadmin') {  echo json_encode(['ok' => false, 'error' => 'Access denied. Developer role required.']);  exit;
}  $action = $_GET['action'] ?? $_POST['action'] ?? '';  // CSRF validation for POST requests
if ($_SERVER['REQUEST_METHOD'] === 'POST') {  $csrf = $_POST['csrf_token'] ?? '';  if (empty($csrf) || $csrf !== ($_SESSION['csrf_token'] ?? '')) {  echo json_encode(['ok' => false, 'error' => 'Invalid CSRF token']);  exit;  }
}  try {  switch ($action) {  // ══════════════════════════════════════════════════════════════  // 1. GET STATION LIST with module summary  // ══════════════════════════════════════════════════════════════  case 'get_stations':  $stmt = $pdo->query("  SELECT  s.id,  s.name,  s.location,  s.region,  s.contact_number,  s.status,  CONCAT(u.first_name, ' ', u.last_name) as assigned_admin,  COUNT(DISTINCT sm.id) as total_modules,  SUM(CASE WHEN sm.is_enabled = 1 THEN 1 ELSE 0 END) as enabled_modules  FROM stations s  LEFT JOIN users u ON u.id = s.admin_id  LEFT JOIN station_modules sm ON sm.station_id = s.id  WHERE s.status = 'Active'  GROUP BY s.id  ORDER BY s.name  ");  echo json_encode(['ok' => true, 'stations' => $stmt->fetchAll(PDO::FETCH_ASSOC)]);  break;  // ══════════════════════════════════════════════════════════════  // 2. GET MODULES for specific station (returns full canonical list)  // ══════════════════════════════════════════════════════════════  case 'get_station_modules':  $station_id = (int)($_GET['station_id'] ?? 0);  if (!$station_id) {  echo json_encode(['ok' => false, 'error' => 'Station ID required']);  exit;  }  // ── Canonical module display order with full metadata ─────────────────  $module_display_order = [  'transactions'  => ['name' => 'Transactions (Merchandise POS)',  'icon' => 'fas fa-cash-register',  'desc' => 'Encode and manage sales, payments, and receipts',  'group' => 'Operational'],  'fuel_management'  => ['name' => 'Fuel Management',  'icon' => 'fas fa-gas-pump',  'desc' => 'Meter readings, reconciliation, variance rules',  'group' => 'Operational'],  'merchandise_deliveries' => ['name' => 'Merchandise Deliveries',  'icon' => 'fas fa-truck-loading',  'desc' => 'Delivery recording, validation, and approval workflow',  'group' => 'Operational'],  'deliveries'  => ['name' => 'Deliveries',  'icon' => 'fas fa-truck',  'desc' => 'Delivery validation and tracking',  'group' => 'Operational'],  'inventory'  => ['name' => 'Inventory',  'icon' => 'fas fa-boxes',  'desc' => 'FIFO rules, stock requests, low-stock alerts',  'group' => 'Operational'],  'product_management'  => ['name' => 'Product Management',  'icon' => 'fas fa-shopping-cart',  'desc' => 'Merchandise catalog setup, pricing, and price approval',  'group' => 'Operational'],  'customers'  => ['name' => 'Customers',  'icon' => 'fas fa-users',  'desc' => 'Loyalty program, balances, credit linkage',  'group' => 'Operational'],  'job_orders'  => ['name' => 'Job Orders',  'icon' => 'fas fa-tools',  'desc' => 'Service / maintenance request workflows',  'group' => 'Operational'],  'purchase_orders'  => ['name' => 'Purchase Orders',  'icon' => 'fas fa-file-invoice-dollar', 'desc' => 'PO creation, approval, and supplier management',  'group' => 'Operational'],  'payments'  => ['name' => 'Payment Methods',  'icon' => 'fas fa-credit-card',  'desc' => 'Payment handling: Cash, Card, E-Wallet, Fleet, Credit',  'group' => 'Operational'],  'calendar'  => ['name' => 'Calendar',  'icon' => 'fas fa-calendar-alt',  'desc' => 'Shift scheduling, delivery events, and system notifications',  'group' => 'Scheduling & Reporting'],  'reports'  => ['name' => 'Reports',  'icon' => 'fas fa-chart-bar',  'desc' => 'Analytics, compliance documentation, and exports',  'group' => 'Scheduling & Reporting'],  'staff_management'  => ['name' => 'Staff Management',  'icon' => 'fas fa-user-tie',  'desc' => 'Attendance, performance, and shift tracking',  'group' => 'Administration'],  'admin_unlock'  => ['name' => 'Admin Unlock',  'icon' => 'fas fa-unlock-alt',  'desc' => 'Override approvals and unlock voided transactions',  'group' => 'Administration'],  'merchandise'  => ['name' => 'Merchandise',  'icon' => 'fas fa-shopping-cart',  'desc' => 'Merchandise inventory and catalog (legacy alias)',  'group' => 'Operational'],  ];  // ── Auto-provision any missing module rows with INSERT IGNORE ─────────  foreach (array_keys($module_display_order) as $mod_key) {  try {  $ins = $pdo->prepare("  INSERT IGNORE INTO station_modules (station_id, module_key, is_enabled, updated_by, updated_at)  VALUES (?, ?, 1, ?, NOW())  ");  $ins->execute([$station_id, $mod_key, $me['id']]);  } catch (Exception $e) { /* skip if table constraints differ */ }  }  // ── Fetch all rows ordered by canonical display order ─────────────────  $order_sql = implode(',', array_map(  fn($k) => $pdo->quote($k),  array_keys($module_display_order)  ));  $stmt = $pdo->prepare("  SELECT  sm.module_key,  sm.is_enabled,  sm.updated_at,  CONCAT(COALESCE(u.first_name,''), ' ', COALESCE(u.last_name,'')) as updated_by_name  FROM station_modules sm  LEFT JOIN users u ON u.id = sm.updated_by  WHERE sm.station_id = ?  ORDER BY FIELD(sm.module_key, $order_sql)  ");  $stmt->execute([$station_id]);  $modules = $stmt->fetchAll(PDO::FETCH_ASSOC);  // ── Attach display metadata ───────────────────────────────────────────  foreach ($modules as &$mod) {  $key = $mod['module_key'];  $info = $module_display_order[$key] ?? null;  $mod['name']  = $info['name']  ?? ucwords(str_replace('_', ' ', $key));  $mod['icon']  = $info['icon']  ?? 'fas fa-cog';  $mod['description'] = $info['desc']  ?? '';  $mod['group']  = $info['group'] ?? 'Other';  }  unset($mod);  echo json_encode(['ok' => true, 'modules' => $modules, 'station_id' => $station_id]);  break;  // ══════════════════════════════════════════════════════════════  // 3. TOGGLE MODULE for specific station  // ══════════════════════════════════════════════════════════════  case 'toggle_module':  $station_id = (int)($_POST['station_id'] ?? 0);  $module_key = $_POST['module_key'] ?? '';  $enabled = (int)($_POST['enabled'] ?? 0);  if (!$station_id || !$module_key) {  echo json_encode(['ok' => false, 'error' => 'Station ID and Module Key required']);  exit;  }  // Get old value  $stmt = $pdo->prepare("SELECT is_enabled FROM station_modules WHERE station_id = ? AND module_key = ?");  $stmt->execute([$station_id, $module_key]);  $old_value = $stmt->fetchColumn();  // Update module status  $stmt = $pdo->prepare("  UPDATE station_modules  SET is_enabled = ?, updated_by = ?, updated_at = NOW()  WHERE station_id = ? AND module_key = ?  ");  $stmt->execute([$enabled, $me['id'], $station_id, $module_key]);  // Get station name for audit  $stmt = $pdo->prepare("SELECT name FROM stations WHERE id = ?");  $stmt->execute([$station_id]);  $station_name = $stmt->fetchColumn();  // Log audit trail  $dev_name = trim(($me['first_name'] ?? '') . ' ' . ($me['last_name'] ?? ''))  ?: ($me['name'] ?? $me['username'] ?? 'Developer');  $stmt = $pdo->prepare("  INSERT INTO station_module_audit  (station_id, module_key, action, old_value, new_value, developer_id, developer_name, ip_address)  VALUES (?, ?, ?, ?, ?, ?, ?, ?)  ");  $stmt->execute([  $station_id,  $module_key,  $enabled ? 'enable' : 'disable',  $old_value,  $enabled,  $me['id'],  $dev_name,  $_SERVER['REMOTE_ADDR'] ?? '0.0.0.0'  ]);  echo json_encode([  'ok' => true,  'message' => "Module '$module_key' " . ($enabled ? 'enabled' : 'disabled') . " for station '$station_name'"  ]);  break;  // ══════════════════════════════════════════════════════════════  // 4. GET FUEL CONFIGURATION for station  // ══════════════════════════════════════════════════════════════  case 'get_fuel_config':  $station_id = (int)($_GET['station_id'] ?? 0);  if (!$station_id) {  echo json_encode(['ok' => false, 'error' => 'Station ID required']);  exit;  }  $stmt = $pdo->prepare("  SELECT * FROM station_fuel_config  WHERE station_id = ?  ORDER BY fuel_type  ");  $stmt->execute([$station_id]);  echo json_encode(['ok' => true, 'fuel_config' => $stmt->fetchAll(PDO::FETCH_ASSOC)]);  break;  // ══════════════════════════════════════════════════════════════  // 5. UPDATE FUEL CONFIGURATION  // ══════════════════════════════════════════════════════════════  case 'update_fuel_config':  $id = (int)($_POST['id'] ?? 0);  $station_id = (int)($_POST['station_id'] ?? 0);  $field = $_POST['field'] ?? '';  $value = $_POST['value'] ?? '';  if (!$id || !$station_id || !$field) {  echo json_encode(['ok' => false, 'error' => 'Invalid parameters']);  exit;  }  // Get old value for audit  $stmt = $pdo->prepare("SELECT $field FROM station_fuel_config WHERE id = ?");  $stmt->execute([$id]);  $old_value = $stmt->fetchColumn();  // Update field  $stmt = $pdo->prepare("  UPDATE station_fuel_config  SET $field = ?, updated_by = ?, updated_at = NOW()  WHERE id = ? AND station_id = ?  ");  $stmt->execute([$value, $me['id'], $id, $station_id]);  // Log audit  $stmt = $pdo->prepare("  INSERT INTO station_module_audit  (station_id, module_key, config_table, action, field_changed, old_value, new_value, developer_id, developer_name, ip_address)  VALUES (?, 'fuel_management', 'station_fuel_config', 'configure', ?, ?, ?, ?, ?, ?)  ");  $dev_name2 = trim(($me['first_name'] ?? '') . ' ' . ($me['last_name'] ?? ''))  ?: ($me['name'] ?? $me['username'] ?? 'Developer');  $stmt->execute([  $station_id,  $field,  $old_value,  $value,  $me['id'],  $dev_name2,  $_SERVER['REMOTE_ADDR'] ?? '0.0.0.0'  ]);  echo json_encode(['ok' => true, 'message' => 'Fuel configuration updated']);  break;  // ══════════════════════════════════════════════════════════════  // 6. GET PAYMENT METHODS for station  // ══════════════════════════════════════════════════════════════  case 'get_payment_config':  $station_id = (int)($_GET['station_id'] ?? 0);  if (!$station_id) {  echo json_encode(['ok' => false, 'error' => 'Station ID required']);  exit;  }  $stmt = $pdo->prepare("  SELECT * FROM station_payment_config  WHERE station_id = ?  ORDER BY payment_method  ");  $stmt->execute([$station_id]);  echo json_encode(['ok' => true, 'payment_config' => $stmt->fetchAll(PDO::FETCH_ASSOC)]);  break;  // ══════════════════════════════════════════════════════════════  // 7. GET INVENTORY CONFIGURATION for station  // ══════════════════════════════════════════════════════════════  case 'get_inventory_config':  $station_id = (int)($_GET['station_id'] ?? 0);  if (!$station_id) {  echo json_encode(['ok' => false, 'error' => 'Station ID required']);  exit;  }  $stmt = $pdo->prepare("  SELECT * FROM station_inventory_config  WHERE station_id = ?  ");  $stmt->execute([$station_id]);  $config = $stmt->fetch(PDO::FETCH_ASSOC);  echo json_encode(['ok' => true, 'inventory_config' => $config]);  break;  // ══════════════════════════════════════════════════════════════  // 8. UPDATE INVENTORY CONFIGURATION  // ══════════════════════════════════════════════════════════════  case 'update_inventory_config':  $station_id = (int)($_POST['station_id'] ?? 0);  $field = $_POST['field'] ?? '';  $value = $_POST['value'] ?? '';  if (!$station_id || !$field) {  echo json_encode(['ok' => false, 'error' => 'Invalid parameters']);  exit;  }  // Get old value  $stmt = $pdo->prepare("SELECT $field FROM station_inventory_config WHERE station_id = ?");  $stmt->execute([$station_id]);  $old_value = $stmt->fetchColumn();  // Update field  $stmt = $pdo->prepare("  UPDATE station_inventory_config  SET $field = ?, updated_by = ?, updated_at = NOW()  WHERE station_id = ?  ");  $stmt->execute([$value, $me['id'], $station_id]);  // Log audit  $stmt = $pdo->prepare("  INSERT INTO station_module_audit  (station_id, module_key, config_table, action, field_changed, old_value, new_value, developer_id, developer_name, ip_address)  VALUES (?, 'inventory', 'station_inventory_config', 'configure', ?, ?, ?, ?, ?, ?)  ");  $stmt->execute([  $station_id,  $field,  $old_value,  $value,  $me['id'],  $me['first_name'] . ' ' . $me['last_name'],  $_SERVER['REMOTE_ADDR'] ?? '0.0.0.0'  ]);  echo json_encode(['ok' => true, 'message' => 'Inventory configuration updated']);  break;  // ══════════════════════════════════════════════════════════════  // 9. GET REPORT CONFIGURATION for station  // ══════════════════════════════════════════════════════════════  case 'get_report_config':  $station_id = (int)($_GET['station_id'] ?? 0);  if (!$station_id) {  echo json_encode(['ok' => false, 'error' => 'Station ID required']);  exit;  }  $stmt = $pdo->prepare("  SELECT * FROM station_report_config  WHERE station_id = ?  ORDER BY report_type  ");  $stmt->execute([$station_id]);  echo json_encode(['ok' => true, 'report_config' => $stmt->fetchAll(PDO::FETCH_ASSOC)]);  break;  // ══════════════════════════════════════════════════════════════  // 10. GET AUDIT LOG for station  // ══════════════════════════════════════════════════════════════  case 'get_audit_log':  $station_id = (int)($_GET['station_id'] ?? 0);  $module_key = $_GET['module_key'] ?? '';  $sql = "  SELECT  sma.created_at,  sma.module_key,  sma.action,  sma.field_changed,  sma.old_value,  sma.new_value,  sma.developer_name,  sma.ip_address  FROM station_module_audit sma  WHERE 1=1  ";  $params = [];  if ($station_id) {  $sql .= " AND sma.station_id = ?";  $params[] = $station_id;  }  if ($module_key) {  $sql .= " AND sma.module_key = ?";  $params[] = $module_key;  }  $sql .= " ORDER BY sma.created_at DESC LIMIT 100";  $stmt = $pdo->prepare($sql);  $stmt->execute($params);  echo json_encode(['ok' => true, 'audit_log' => $stmt->fetchAll(PDO::FETCH_ASSOC)]);  break;  default:  echo json_encode(['ok' => false, 'error' => 'Unknown action']);  break;  }  } catch (Exception $e) {  echo json_encode(['ok' => false, 'error' => 'Server error: ' . $e->getMessage()]);
}
?>
